// Volumetric conical spiral with directional fading
float spiralDensity(vec3 p) {
    float density = 0.0;
    float frequency = 6.0;
    float z = p.z;
    float lengthDecay = 0.25; // Controls how fast it fades along the spiral

    // Sample points with phase offset
    for(int i = -4; i <= 4; i++) {
        float spiralPos = z + float(i) * 0.25; // Position along spiral
        float radius = 0.12 * spiralPos; // Spiral expansion rate
        float theta = frequency * spiralPos; // Angular position

        vec3 spiralPoint = vec3(
            radius * cos(theta),
            radius * sin(theta),
            spiralPos
        );

        // Distance to spiral arm with exponential falloff
        float dist = length(p - spiralPoint);

        // Fade based on position along spiral
        float positionFade = exp(-lengthDecay * spiralPos);

        density += exp(-30.0 * dist*dist) * positionFade;
    }

    return density;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // Camera setup
    vec3 ro = vec3(0.0, 0.5, -5.0);
    vec3 rd = normalize(vec3(uv, 1.2));

    // Camera rotation
    float angle = iTime * 0.2;
    rd.xz = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * rd.xz;
    ro.xz = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * ro.xz;

    // Raymarching parameters
    float t = 0.0;
    const float stepSize = 0.06;
    const int steps = 150;

    vec3 col = vec3(0.0);
    float transmittance = 1.0;

    // Volumetric integration
    for(int i = 0; i < steps; i++) {
        vec3 p = ro + rd * t;

        // Get density and apply color
        float density = spiralDensity(p);
        vec3 emission = vec3(0.3, 0.6, 1.0) * density;
        float absorption = 0.15 * density;

        // Volume rendering
        transmittance *= exp(-absorption * stepSize);
        col += emission * transmittance * stepSize;

        t += stepSize;

        // Early exit when opaque enough
        if(transmittance < 0.01) break;
    }

    // Add distance-based atmospheric fade
    col *= exp(-0.03 * t);

    // Gamma correction
    col = pow(col, vec3(0.4545));

    fragColor = vec4(col, 1.0);
}
